changeSet.sql:
CREATE TABLE outbox_emails ( id BIGSERIAL PRIMARY KEY, payload JSONB NOT NULL, status TEXT NOT NULL CHECK ( status IN ('NEW', 'SENT', 'FAILED') ), type TEXT NOT NULL CHECK ( type IN ('WELCOME', 'REPORT') ), dedup_key TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
CONSTRAINT uq_outbox_emails_dedup_key_type UNIQUE (dedup_key, type) );
CREATE INDEX idx_outbox_emails_status_next_attempt ON outbox_emails (status, next_attempt_at);
